    laneS: 0,
    x: 0,
    xv: 0,
    yaw: 0,
    yawV: 0,
    camX: 0,
    camXv: 0,
    steer: 0,
    steerV: 0,
    cur: 0,
    autoOn: 1,
    autoT0: 0,
    autoPos0: 0,
    // the game: run counter, the cruise segment it belongs to, game-over kind (1 crashed, 2 busted) and time,
